use t3_protocol::{Connection,Credential};use serde_json::{json,Value};use std::{net::TcpListener,thread};
#[test]
fn favorites_use_server_settings_and_desired_instance_state(){
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();let url=format!("http://{}",listener.local_addr().unwrap());
 let server=thread::spawn(move||{for (tag,result) in [("server.getConfig",json!({"providers":[],"settings":{"favorites":[{"provider":"work","model":"same"}]}})),("server.getSettings",json!({"favorites":[{"provider":"work","model":"same"}]})),("server.updateSettings",json!({"favorites":[{"provider":"work","model":"same"},{"provider":"personal","model":"same"}],"privateToken":"never-export"})),("server.getSettings",json!({"favorites":null}))]{let (s,_)=listener.accept().unwrap();let mut ws=tungstenite::accept(s).unwrap();let request:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();assert_eq!(request["tag"],tag);if tag=="server.updateSettings"{assert_eq!(request["payload"],json!({"patch":{"setModelFavorites":[{"provider":"personal","model":"same","favorite":true}]}}));}ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":result}}).to_string().into())).unwrap();}});
 let c=Connection::new(&url,None,Credential::bearer("synthetic-credential").unwrap()).unwrap();let catalog=c.model_catalog().unwrap();assert_eq!(catalog["favorites"][0]["provider"],"work");let result=c.set_model_favorite("personal","same",true).unwrap();assert_eq!(result["favorites"].as_array().unwrap().len(),2);assert!(!result.to_string().contains("never-export"));assert_eq!(c.set_model_favorite("personal","same",true).unwrap_err(),"model_preferences_uninitialized");server.join().unwrap();
}
